	private static LmdbStore reopenSeeded(File directory) {
		LmdbStore seed = new LmdbStore(directory, new LmdbStoreConfig("spoc,posc"));
		seed.init();
		try (SailConnection connection = seed.getConnection()) {
			connection.begin(IsolationLevels.SNAPSHOT);
			TripleTerm inner = VF.createTripleTerm(VF.createBNode("callback-inner"),
					VF.createIRI("urn:callback:inner-predicate"), VF.createLiteral(LABEL, VF.createIRI(DATATYPE)));
			TripleTerm outer = VF.createTripleTerm(VF.createIRI("urn:callback:outer"),
					VF.createIRI("urn:callback:outer-predicate"), inner);
			connection.addStatement(SUBJECT, PREDICATE, outer);
			TripleTerm probeInner = VF.createTripleTerm(VF.createBNode("callback-probe-inner"),
					VF.createIRI("urn:callback:probe-inner-predicate"),
					VF.createLiteral(LABEL + " probe", VF.createIRI(DATATYPE + ":probe")));
			connection.addStatement(VF.createIRI("urn:callback:probe"), PROBE_PREDICATE,
					VF.createTripleTerm(VF.createIRI("urn:callback:probe-outer"),
							VF.createIRI("urn:callback:probe-outer-predicate"), probeInner));
			connection.commit();
		} finally {
			seed.shutDown();
		}
		return new LmdbStore(directory, new LmdbStoreConfig("spoc,posc"));
	}

	private static void assertStatementProtected(Statement statement) {
		assertProtected(statement.getSubject());
		assertProtected(statement.getPredicate());
		assertProtected(statement.getObject());
		assertProtected(statement.getContext());
	}

	private static void assertProtected(Value value) {
		if (value instanceof LmdbValue lmdb) {
			assertTrue(lmdb.isExternallyOwned(), "Callback values must retain cold ownership before being returned");
			// Inspect only already published children: testing ownership must not itself decode deferred payloads.
			lmdb.visitValueChildren(LmdbExternalValueBoundaryTest::assertProtected);
		} else if (value instanceof TripleTerm triple) {
			assertProtected(triple.getSubject());
			assertProtected(triple.getPredicate());
			assertProtected(triple.getObject());
		} else if (value instanceof Literal literal) {
			assertProtected(literal.getDatatype());
		}
	}

	private static void assertDeepReady(Value value) {
		if (value instanceof LmdbValue lmdb) {
			assertInstanceOf(ValueStoreRevision.Default.class, lmdb.getValueStoreRevision(),
					"Repository results must be ready before any lexical getter runs");
		}
		if (value instanceof TripleTerm triple) {
			assertDeepReady(triple.getSubject());
			assertDeepReady(triple.getPredicate());
			assertDeepReady(triple.getObject());
		} else if (value instanceof Literal literal) {
			assertDeepReady(literal.getDatatype());
		}
	}

	private static void assertRetainedLexicalValues(Value value) {
		if (value instanceof TripleTerm triple) {
			assertRetainedLexicalValues(triple.getSubject());
			assertRetainedLexicalValues(triple.getPredicate());
			assertRetainedLexicalValues(triple.getObject());
		} else if (value instanceof Literal literal) {
			assertTrue(LITERAL_DATATYPES.containsKey(literal.getLabel()));
			assertEquals(LITERAL_DATATYPES.get(literal.getLabel()), literal.getDatatype().stringValue());
		} else {
			assertFalse(value.stringValue().isEmpty());
		}
	}
